#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
SMA RS485 Inverter Reader - 100% STANDALONE SINGLE-FILE EXECUTABLE
-------------------------------------------------------------------
- ONE SINGLE FILE: No external .tar.gz, no setup scripts, no dependencies!
- Contains embedded native Raspberry Pi (ARM64) YASDI libraries.
- Self-extracts to /usr/local/lib or ~/.sma_libs and configures system automatically.
- Works on ANY fresh/clean Raspberry Pi straight out of the box!
- Reads ALL spot channels (Pac, Pdc, Vdc, Idc, E-Today, E-Total, Mode, etc.)
- Summary Table + Full Channel Dump + CSV/JSON exports.
"""

import os
import sys
import time
import glob
import csv
import json
import ctypes
import base64
import zlib
import subprocess
from datetime import datetime

SCRIPT_DIR = os.path.dirname(os.path.abspath(__file__))
YASDI_CONF_PATH = os.path.join(SCRIPT_DIR, "yasdi.conf")
DEVICES_DIR = os.path.join(SCRIPT_DIR, "devices")
CSV_LOG_PATH = os.path.join(SCRIPT_DIR, "sma_data.csv")
JSON_ALL_CHANNELS_PATH = os.path.join(SCRIPT_DIR, "sma_all_channels.json")
BASELINE_PATH = os.path.join(SCRIPT_DIR, "sma_daily_baseline.json")

os.makedirs(DEVICES_DIR, exist_ok=True)

FIXED_BAUDRATE = 1200

SPOTCHANNELS = 0
PARAMCHANNELS = 1
TESTCHANNELS = 2
ALLCHANNELS = 3

EMBEDDED_ARM64_LIBS = {
    'libyasdi': '',
    'libyasdimaster': '',
    'libyasdi_drv_serial': '',
}


def auto_setup_and_extract_libs():
    """
    Auto-detects if YASDI is installed on the system.
    If running on a brand-new Raspberry Pi, extracts embedded native ARM64 libraries
    directly into /usr/local/lib or local lib directory and runs ldconfig.
    """
    if os.path.exists("/usr/local/lib/libyasdimaster.so"):
        return "/usr/local/lib"

    print("[*] Fresh system detected: Auto-installing YASDI libraries...")

    target_dir = "/usr/local/lib"
    can_write_root = True
    try:
        test_f = "/usr/local/lib/.test_w"
        with open(test_f, "w") as f: f.write("1")
        os.remove(test_f)
    except Exception:
        can_write_root = False

    if not can_write_root:
        # Check if sudo works without password
        res = subprocess.run("sudo -n true 2>/dev/null", shell=True)
        if res.returncode != 0:
            target_dir = os.path.join(os.path.expanduser("~"), ".sma_libs")
            os.makedirs(target_dir, exist_ok=True)

    print(f"[*] Extracting libraries to: {target_dir}")

    lib_files = {
        'libyasdi.so': 'libyasdi',
        'libyasdi.so.1': 'libyasdi',
        'libyasdi.so.1.8.1': 'libyasdi',
        'libyasdimaster.so': 'libyasdimaster',
        'libyasdimaster.so.1': 'libyasdimaster',
        'libyasdimaster.so.1.8.1': 'libyasdimaster',
        'libyasdi_drv_serial.so': 'libyasdi_drv_serial',
        'libyasdi_drv_serial.so.1': 'libyasdi_drv_serial',
        'libyasdi_drv_serial.so.1.8.1': 'libyasdi_drv_serial',
    }

    decompressed_cache = {}
    for key, b64_str in EMBEDDED_ARM64_LIBS.items():
        decompressed_cache[key] = zlib.decompress(base64.b64decode(b64_str))

    for filename, raw_key in lib_files.items():
        dest = os.path.join(target_dir, filename)
        raw = decompressed_cache[raw_key]
        if can_write_root or target_dir != "/usr/local/lib":
            with open(dest, "wb") as f:
                f.write(raw)
            os.chmod(dest, 0o755)
        else:
            tmp_p = f"/tmp/{filename}"
            with open(tmp_p, "wb") as f:
                f.write(raw)
            subprocess.run(f"sudo mv {tmp_p} /usr/local/lib/ && sudo chmod 755 /usr/local/lib/{filename}", shell=True)

    # Multiarch support for Debian / Ubuntu ARM64
    multiarch_dir = "/usr/lib/aarch64-linux-gnu"
    if os.path.isdir(multiarch_dir) and target_dir == "/usr/local/lib":
        subprocess.run(f"sudo cp -a /usr/local/lib/libyasdi* {multiarch_dir}/ 2>/dev/null || true", shell=True)

    if target_dir == "/usr/local/lib":
        subprocess.run("sudo ldconfig 2>/dev/null || sudo /sbin/ldconfig 2>/dev/null || ldconfig 2>/dev/null || true", shell=True)
    else:
        # Add local dir to LD_LIBRARY_PATH
        if target_dir not in os.environ.get("LD_LIBRARY_PATH", ""):
            cur_ld = os.environ.get("LD_LIBRARY_PATH", "")
            os.environ["LD_LIBRARY_PATH"] = f"{target_dir}:{cur_ld}" if cur_ld else target_dir
            try:
                os.execv(sys.executable, [sys.executable] + sys.argv)
            except Exception:
                pass

    print("[✓] YASDI libraries installed successfully!")
    return target_dir


def get_or_update_daily_baseline(sn, current_etotal):
    today_str = datetime.now().strftime("%Y-%m-%d")
    baselines = {}

    if os.path.exists(BASELINE_PATH):
        try:
            with open(BASELINE_PATH, "r") as f:
                baselines = json.load(f)
        except Exception:
            baselines = {}

    sn_key = str(sn)
    
    if sn_key not in baselines or baselines[sn_key].get("date") != today_str:
        baselines[sn_key] = {
            "date": today_str,
            "baseline_kwh": current_etotal
        }
        try:
            with open(BASELINE_PATH, "w") as f:
                json.dump(baselines, f, indent=2)
        except Exception:
            pass

    start_kwh = baselines[sn_key].get("baseline_kwh", current_etotal)
    etoday = max(0.0, current_etotal - start_kwh)
    return etoday


def list_available_serial_ports():
    return sorted(glob.glob("/dev/ttyUSB*"))


def get_user_inputs():
    print("=" * 76)
    print("      SMA RS485 Inverter Reader - Sunny Mini Central (SMC 7000TL)      ")
    print("=" * 76)

    available_ports = list_available_serial_ports()
    if available_ports:
        print(f"[*] Available USB ports: {', '.join(available_ports)}")
    else:
        print("[!] Warning: No active /dev/ttyUSB* device detected at this moment.")

    if len(sys.argv) >= 3:
        usb_input = sys.argv[1]
        count_input = sys.argv[2]
    elif len(sys.argv) == 2:
        usb_input = sys.argv[1]
        count_input = "2"
    else:
        default_usb = "0"
        if available_ports:
            default_usb = available_ports[0].replace("/dev/ttyUSB", "")

        usb_prompt = input(f"\n[?] Enter USB port number (e.g. 0 for ttyUSB0, 1 for ttyUSB1) [{default_usb}]: ").strip()
        usb_input = usb_prompt if usb_prompt else default_usb

        count_prompt = input("[?] How many inverters do you want to read? [2]: ").strip()
        count_input = count_prompt if count_prompt else "2"

    if usb_input.startswith("/dev/ttyUSB"):
        port_device = usb_input
    else:
        port_device = f"/dev/ttyUSB{usb_input}"

    try:
        dev_count = int(count_input)
    except ValueError:
        dev_count = 2

    return port_device, dev_count


def generate_yasdi_conf(port_device):
    if os.path.exists(YASDI_CONF_PATH):
        try:
            with open(YASDI_CONF_PATH, "r") as f:
                cur = f.read()
            if f"Device={port_device}" in cur:
                # Keep user's custom settings intact (e.g. Media=RS485)
                return
        except Exception:
            pass

    conf_content = f"""[DriverModules]
Driver0=yasdi_drv_serial

[COM1]
Device={port_device}
DeviceFilesPath={DEVICES_DIR}
Media=RS485
Baudrate={FIXED_BAUDRATE}
Protocol=SMANet
"""
    with open(YASDI_CONF_PATH, "w") as f:
        f.write(conf_content)


def load_yasdi_library():
    lib_dir = auto_setup_and_extract_libs()

    lib_yasdi_p = os.path.join(lib_dir, "libyasdi.so") if os.path.exists(os.path.join(lib_dir, "libyasdi.so")) else "libyasdi.so"
    lib_master_p = os.path.join(lib_dir, "libyasdimaster.so") if os.path.exists(os.path.join(lib_dir, "libyasdimaster.so")) else "libyasdimaster.so"

    try:
        ctypes.CDLL(lib_yasdi_p, mode=ctypes.RTLD_GLOBAL)
    except Exception:
        ctypes.CDLL("libyasdi.so", mode=ctypes.RTLD_GLOBAL)

    try:
        lib = ctypes.CDLL(lib_master_p, mode=ctypes.RTLD_GLOBAL)
    except Exception:
        lib = ctypes.CDLL("libyasdimaster.so", mode=ctypes.RTLD_GLOBAL)

    DWORD = ctypes.c_uint32
    BOOL = ctypes.c_int

    lib.yasdiMasterInitialize.argtypes = [ctypes.c_char_p, ctypes.POINTER(DWORD)]
    lib.yasdiMasterInitialize.restype = ctypes.c_int

    lib.yasdiMasterShutdown.argtypes = []
    lib.yasdiMasterShutdown.restype = None

    lib.yasdiMasterSetDriverOnline.argtypes = [DWORD]
    lib.yasdiMasterSetDriverOnline.restype = BOOL

    lib.DoStartDeviceDetection.argtypes = [ctypes.c_int, BOOL]
    lib.DoStartDeviceDetection.restype = ctypes.c_int

    lib.DoStopDeviceDetection.argtypes = []
    lib.DoStopDeviceDetection.restype = ctypes.c_int

    EVENT_CALLBACK_TYPE = ctypes.CFUNCTYPE(None, ctypes.c_int, DWORD, DWORD)
    lib.yasdiMasterAddEventListener.argtypes = [EVENT_CALLBACK_TYPE, DWORD]
    lib.yasdiMasterAddEventListener.restype = ctypes.c_int

    lib.GetDeviceHandles.argtypes = [ctypes.POINTER(DWORD), DWORD]
    lib.GetDeviceHandles.restype = DWORD

    lib.GetDeviceName.argtypes = [DWORD, ctypes.c_char_p, ctypes.c_int]
    lib.GetDeviceName.restype = ctypes.c_int

    lib.GetDeviceType.argtypes = [DWORD, ctypes.c_char_p, ctypes.c_int]
    lib.GetDeviceType.restype = ctypes.c_int

    lib.GetDeviceSN.argtypes = [DWORD, ctypes.POINTER(DWORD)]
    lib.GetDeviceSN.restype = ctypes.c_int

    lib.GetChannelHandlesEx.argtypes = [DWORD, ctypes.POINTER(DWORD), DWORD, ctypes.c_int]
    lib.GetChannelHandlesEx.restype = DWORD

    lib.GetChannelName.argtypes = [DWORD, ctypes.c_char_p, ctypes.c_int]
    lib.GetChannelName.restype = ctypes.c_int

    lib.GetChannelUnit.argtypes = [DWORD, ctypes.c_char_p, ctypes.c_int]
    lib.GetChannelUnit.restype = ctypes.c_int

    lib.GetChannelValue.argtypes = [
        DWORD,
        DWORD,
        ctypes.POINTER(ctypes.c_double),
        ctypes.c_char_p,
        ctypes.c_int,
        DWORD
    ]
    lib.GetChannelValue.restype = ctypes.c_int

    return lib


def dump_all_channels_for_device(lib, dev_handle, dev_index, chan_type=SPOTCHANNELS):
    sn = ctypes.c_uint32(0)
    lib.GetDeviceSN(dev_handle, ctypes.byref(sn))

    name_buf = ctypes.create_string_buffer(64)
    lib.GetDeviceName(dev_handle, name_buf, 64)
    dev_name = name_buf.value.decode("ascii", errors="ignore").strip()

    type_buf = ctypes.create_string_buffer(64)
    lib.GetDeviceType(dev_handle, type_buf, 64)
    dev_type = type_buf.value.decode("ascii", errors="ignore").strip()

    chan_handles = (ctypes.c_uint32 * 500)()
    chan_count = lib.GetChannelHandlesEx(dev_handle, chan_handles, 500, chan_type)

    channels_data = {}
    table_rows = []

    for i in range(chan_count):
        h_chan = chan_handles[i]

        name_buf = ctypes.create_string_buffer(64)
        lib.GetChannelName(h_chan, name_buf, 64)
        ch_name = name_buf.value.decode("ascii", errors="ignore").strip()

        unit_buf = ctypes.create_string_buffer(32)
        lib.GetChannelUnit(h_chan, unit_buf, 32)
        ch_unit = unit_buf.value.decode("ascii", errors="ignore").strip()

        val = ctypes.c_double(0.0)
        val_text = ctypes.create_string_buffer(64)
        ret = lib.GetChannelValue(h_chan, dev_handle, ctypes.byref(val), val_text, 64, 5)

        if ret == 0:
            text_str = val_text.value.decode("ascii", errors="ignore").strip()
            if not text_str:
                text_str = f"{val.value:.3f}".rstrip('0').rstrip('.') if '.' in f"{val.value:.3f}" else f"{val.value:.0f}"

            channels_data[ch_name] = {
                "handle": h_chan,
                "value": text_str,
                "unit": ch_unit,
                "numeric": val.value
            }
            unit_display = f"({ch_unit})" if ch_unit else ""
            table_rows.append((h_chan, ch_name, text_str, unit_display))
        else:
            channels_data[ch_name] = {
                "handle": h_chan,
                "value": "N/A",
                "unit": ch_unit,
                "numeric": None
            }
            table_rows.append((h_chan, ch_name, "N/A", ""))

    return {
        "index": dev_index,
        "dev_handle": dev_handle,
        "sn": sn.value,
        "name": dev_name,
        "type": dev_type,
        "channels": channels_data,
        "table_rows": table_rows
    }


def print_device_channels_table(dev_data, etoday_calc):
    print("\n" + "=" * 70)
    print(f" Device #{dev_data['index']}: {dev_data['type']} '{dev_data['name']}' (SN: {dev_data['sn']})")
    print(f" Total channels: {len(dev_data['table_rows'])} | Calculated E-Today: {etoday_calc:.2f} kWh")
    print("-" * 70)
    print(f"{'Channel handle':<16} | {'Channel name':<24} | {'Channel value (Unit)'}")
    print("-" * 70)

    for h_chan, ch_name, text_str, unit_disp in dev_data["table_rows"]:
        val_str = f"'{text_str}' {unit_disp}".strip()
        print(f"      {h_chan:<9} | {ch_name:<24} | {val_str}")

    print("=" * 70)


def extract_key_metrics(chans, sn):
    def get_val(aliases):
        for a in aliases:
            for k, v in chans.items():
                if k.lower() == a.lower():
                    return v["value"], v["numeric"]
        return "N/A", 0.0

    pac_str, _ = get_val(["Pac", "GridMs.TotW", "Spot.Pac", "Pac-Ist"])
    vol_str, _ = get_val(["A.Ms.Vol", "GridMs.PhV.phsA", "Spot.Uac", "Upv-Ist", "Vac", "Uac"])
    amp_str, _ = get_val(["A.Ms.Amp", "GridMs.A.phsA", "Spot.Iac", "Ipv", "Iac"])
    pdc_str, _ = get_val(["A.Ms.Watt", "Pdc", "Spot.Pdc"])
    etot_str, etot_num = get_val(["E-Total", "Metering.TotWhOut", "Spot.ETotal", "Total-Energy", "E_Total", "ETotal"])
    mode_str, _ = get_val(["Mode", "Status", "OperatingStt"])
    error_str, _ = get_val(["Error", "Fehler"])

    try:
        etot_float = float(etot_str) if etot_str != "N/A" else float(etot_num)
    except ValueError:
        etot_float = 0.0

    etoday_calc = get_or_update_daily_baseline(sn, etot_float)
    etoday_str = f"{etoday_calc:.2f}"

    return pac_str, pdc_str, vol_str, amp_str, etoday_str, etoday_calc, etot_str, mode_str, error_str


def print_summary_table(all_devices_data):
    print("\n" + "=" * 114)
    print("                             SUMMARY TABLE - ALL SMA INVERTERS")
    print("=" * 114)
    print(f"{'#':<3} | {'Serial No':<12} | {'Type / Name':<20} | {'Pac (W)':<8} | {'Pdc (W)':<8} | {'Vdc (V)':<8} | {'E-Today (kWh)':<14} | {'E-Total (kWh)':<14} | {'Status'}")
    print("-" * 114)

    for d in all_devices_data:
        pac, pdc, vol, amp, etoday_str, _, etot, mode, _ = extract_key_metrics(d["channels"], d["sn"])
        disp_desc = f"{d['type']} ({d['name']})" if d['name'] else d['type']
        print(f"{d['index']:<3} | {d['sn']:<12} | {disp_desc:<20} | {pac:<8} | {pdc:<8} | {vol:<8} | {etoday_str:<14} | {etot:<14} | {mode}")

    print("=" * 114)


def save_data(all_devices_data):
    timestamp_str = datetime.now().strftime("%Y-%m-%d %H:%M:%S")

    csv_exists = os.path.exists(CSV_LOG_PATH)
    with open(CSV_LOG_PATH, "a", newline="", encoding="utf-8") as f:
        writer = csv.writer(f)
        if not csv_exists:
            writer.writerow([
                "Timestamp", "Inverter_Index", "Serial_Number", "Device_Name",
                "Device_Type", "Pac_W", "Pdc_W", "Vdc_V", "Idc_A", "E_Today_kWh", "E_Total_kWh", "Mode", "Error"
            ])
        for d in all_devices_data:
            pac, pdc, vol, amp, etoday_str, _, etot, mode, error = extract_key_metrics(d["channels"], d["sn"])
            writer.writerow([
                timestamp_str,
                d["index"],
                d["sn"],
                d["name"],
                d["type"],
                pac, pdc, vol, amp, etoday_str, etot, mode, error
            ])

    json_payload = {
        "timestamp": timestamp_str,
        "inverters_count": len(all_devices_data),
        "inverters": []
    }
    for d in all_devices_data:
        pac, pdc, vol, amp, etoday_str, etoday_calc, etot, mode, error = extract_key_metrics(d["channels"], d["sn"])
        d_copy = dict(d["channels"])
        d_copy["E-Today-Calculated"] = {
            "value": etoday_str,
            "unit": "kWh",
            "numeric": etoday_calc
        }
        json_payload["inverters"].append({
            "index": d["index"],
            "serial_number": d["sn"],
            "device_name": d["name"],
            "device_type": d["type"],
            "etoday_kwh": etoday_calc,
            "channels": d_copy
        })

    with open(JSON_ALL_CHANNELS_PATH, "w", encoding="utf-8") as f:
        json.dump(json_payload, f, indent=2, ensure_ascii=False)

    print(f"\n[✓] Key metrics saved to: {CSV_LOG_PATH}")
    print(f"[✓] ALL channels (full dump) saved to: {JSON_ALL_CHANNELS_PATH}")


def main():
    port_device, target_count = get_user_inputs()

    print(f"\n[*] Port: {port_device} | Baudrate: {FIXED_BAUDRATE} (Fixed) | Target: {target_count} inverters (SMC 7000TL)")
    generate_yasdi_conf(port_device)

    print("[*] Loading YASDI Engine...")
    try:
        lib = load_yasdi_library()
    except Exception as e:
        print(f"[-] Loading error: {e}")
        sys.exit(1)

    dwBDC = ctypes.c_uint32(0)
    ret = lib.yasdiMasterInitialize(YASDI_CONF_PATH.encode("utf-8"), ctypes.byref(dwBDC))
    if ret < 0 or dwBDC.value == 0:
        print(f"[-] Failed to start driver for port {port_device}.")
        print("    Check if port is connected and permissions are granted (e.g. sudo chmod 777 /dev/ttyUSB0).")
        sys.exit(1)

    try:
        lib.yasdiMasterSetDriverOnline(0)
        print(f"[+] Driver ONLINE on {port_device}.")

        EVENT_CALLBACK_TYPE = ctypes.CFUNCTYPE(None, ctypes.c_int, ctypes.c_uint32, ctypes.c_uint32)
        event_detected_handles = []

        def event_callback(event, dev_handle, param1):
            if event == 0:  # YASDI_EVENT_DEVICE_ADDED
                if dev_handle not in event_detected_handles:
                    event_detected_handles.append(dev_handle)

        cb_holder = EVENT_CALLBACK_TYPE(event_callback)
        lib.yasdiMasterAddEventListener(cb_holder, 0)

        print(f"[*] Starting detection for {target_count} inverters...")

        lib.DoStartDeviceDetection(target_count, 0)

        handles = (ctypes.c_uint32 * 50)()
        start_time = time.time()
        # Scale detection timeout: 1200 baud is slow on RS485. Allow at least 60s, or ~8s per inverter
        max_wait = max(60, target_count * 8)
        found_count = 0

        while time.time() - start_time < max_wait:
            cnt_api = lib.GetDeviceHandles(handles, 50)
            found_count = max(cnt_api, len(event_detected_handles))
            elapsed = time.time() - start_time
            print(f"[*] Waiting for reply: {found_count}/{target_count} found ({elapsed:.1f}s / {max_wait}s)...", end="\r")
            if found_count >= target_count:
                break
            time.sleep(0.5)

        print()
        lib.DoStopDeviceDetection()
        cnt_api = lib.GetDeviceHandles(handles, 50)

        all_final_handles = []
        for i in range(cnt_api):
            if handles[i] not in all_final_handles:
                all_final_handles.append(handles[i])
        for h in event_detected_handles:
            if h not in all_final_handles:
                all_final_handles.append(h)

        found_count = len(all_final_handles)
        elapsed = time.time() - start_time
        print(f"[✓] Detection completed in {elapsed:.1f}s.")
        print(f"[+] Total devices found and responding: {found_count}")

        if found_count == 0:
            print("\n[-] No SMA inverters responded.")
            print("    Hardware troubleshooting checklist for SMC 7000TL:")
            print("    1. Terminal wiring (485PB-SMC-NR): Pin 2 = Data+ (A+), Pin 7 = Data- (B-), Pin 5 = GND.")
            print("    2. Bus Termination (Jumper A): Must be ON ONLY on the last inverter. OFF on all others!")
            print("    3. DC Voltage: Ensure PV panels have voltage/sunlight (inverters turn off at night).")
            return

        # YASDI State Identification Phase:
        # After device detection, YASDI requests the channel lists over RS485 for any new device types.
        # Wait up to 15s for the in-memory channel lists to become available.
        print("[*] Synchronizing channel definitions over RS485...")
        for _ in range(15):
            has_channels = False
            for h in all_final_handles:
                chans_test = (ctypes.c_uint32 * 10)()
                if lib.GetChannelHandlesEx(h, chans_test, 10, SPOTCHANNELS) > 0:
                    has_channels = True
                    break
            if has_channels:
                break
            time.sleep(1)

        def process_and_display():
            all_devices_data = []
            for i, h_dev in enumerate(all_final_handles):
                dev_data = dump_all_channels_for_device(lib, h_dev, i + 1, chan_type=SPOTCHANNELS)
                all_devices_data.append(dev_data)

            for dev_data in all_devices_data:
                _, _, _, _, _, etoday_c, _, _, _ = extract_key_metrics(dev_data["channels"], dev_data["sn"])
                print_device_channels_table(dev_data, etoday_c)

            print_summary_table(all_devices_data)
            save_data(all_devices_data)

        process_and_display()

        print("\n[?] Continuously poll at regular intervals? (e.g. type 15 for every 15s, or press Enter to exit): ", end="")
        sys.stdout.flush()
        user_loop = input().strip()

        if user_loop.isdigit() and int(user_loop) > 0:
            interval = int(user_loop)
            print(f"[*] Starting continuous monitoring every {interval}s (Press Ctrl+C to stop)...")
            while True:
                time.sleep(interval)
                process_and_display()

    except KeyboardInterrupt:
        print("\n[*] Stopped by user (Ctrl+C).")
    finally:
        print("[*] Shutting down YASDI engine (releasing resources)...")
        lib.yasdiMasterShutdown()
        print("[✓] Done. Goodbye!\n")


if __name__ == "__main__":
    main()
